  display: inline-flex;
  border-radius: 10px;
  font-family: "Roboto", sans-serif;
  font-size: 0.75rem;
  font-weight: 500;
  height: 1.25rem;
  justify-content: center;
  min-width: 20px;
  padding: 4px 6px;
  pointer-events: auto;
  position: absolute;
  text-align: center;
  text-indent: 0;
  transition: 0.225s cubic-bezier(0.4, 0, 0.2, 1);
  white-space: nowrap;
}
:where(.vuetify-styles) .v-badge__badge {
  background: rgb(var(--v-theme-surface-variant));
  color: rgba(var(--v-theme-on-surface-variant), var(--v-high-emphasis-opacity));
