  position: relative;
  vertical-align: middle;
}
:where(.vuetify-styles) .v-badge__badge .v-icon {
  color: inherit;
  font-size: 0.75rem;
  margin: 0 -2px;
}
:where(.vuetify-styles) .v-badge__badge img,
:where(.vuetify-styles) .v-badge__badge .v-img {
  height: 100%;
  width: 100%;
}

:where(.vuetify-styles) .v-badge__wrapper {
  display: flex;
  position: relative;
}
:where(.vuetify-styles) .v-badge--inline .v-badge__wrapper {
  align-items: center;
  display: inline-flex;
  justify-content: center;
  margin: 0 4px;
